_EXPR_REGISTRY: Optional[Dict[str, Any]] = None
_EXPR_TAGS_BY_CLASS: Dict[type, str] = {}


def _expr_registry() -> Dict[str, Any]:
    """Wire tag -> class, in the order ``ast.rs`` declares the variants.

    Built on first use rather than at import time: see the note above.
    """
    global _EXPR_REGISTRY, _EXPR_TAGS_BY_CLASS
    if _EXPR_REGISTRY is None:
        from ._dto import Arguments, CallExpr, CheckExpr, CompClause, Identifier, Keyword, SchemaExpr, Target
        _EXPR_REGISTRY = {
            "Target": Target,
            "Identifier": Identifier,
            "Unary": UnaryExpr,
            "Binary": BinaryExpr,
            "If": IfExpr,
            "Selector": SelectorExpr,
            "Call": CallExpr,
            "Paren": ParenExpr,
            "Quant": QuantExpr,
            "List": ListExpr,
            "ListIfItem": ListIfItemExpr,
            "ListComp": ListComp,
            "Starred": StarredExpr,
            "DictComp": DictComp,
            "ConfigIfEntry": ConfigIfEntryExpr,
            "CompClause": CompClause,
            "Schema": SchemaExpr,
            "Config": ConfigExpr,
            "Check": CheckExpr,
            "Lambda": LambdaExpr,
            "Subscript": Subscript,
            "Keyword": Keyword,
            "Arguments": Arguments,
            "Compare": Compare,
            "NumberLit": NumberLit,
            "StringLit": StringLit,
            "NameConstantLit": NameConstantLit,
            "JoinedString": JoinedString,
            "FormattedValue": FormattedValue,
            "Missing": MissingExpr,
}
        _EXPR_TAGS_BY_CLASS = {cls: tag for tag, cls in _EXPR_REGISTRY.items()}
    return _EXPR_REGISTRY


def _expr_tag_for(cls: type) -> Optional[str]:
    """The wire tag for a variant class — the inverse of the registry."""
    if not _EXPR_TAGS_BY_CLASS:
        _expr_registry()
    return _EXPR_TAGS_BY_CLASS.get(cls)


def expr_from_dict(d: Any) -> Any:
    """Polymorphic ``Expr`` loader — the mirror of :func:`expr_to_dict`.

    An unrecognised tag decodes to :class:`UnknownExpr`, which keeps the raw
    tag and payload so a forward-compatible parser output survives the round
    trip instead of being dropped.
    """
    d = d if isinstance(d, dict) else {}
    tag = d.get("type") or ""
    cls = _expr_registry().get(tag)
    if cls is None:
        return UnknownExpr.from_dict(d)
    return cls.from_dict(d)


def expr_to_dict(s: Any) -> Any:
    """Polymorphic ``Expr`` serializer — the mirror of :func:`expr_from_dict`."""
    if s is None:
        return None
    if isinstance(s, UnknownExpr):
        return s.to_dict()
    tag = _expr_tag_for(type(s))
    if tag is None:
        raise TypeError("not a Expr variant: %s" % type(s).__name__)
    out = {"type": tag}
    out.update(s.to_dict())
    return out

